package com.mitraa.hackathon.team;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="team_members")
public class TeamMember { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="team_id") private Team team; @Column(nullable=false,length=120) private String fullName; @Column(nullable=false,length=190) private String email; @Column(nullable=false) private LocalDate dateOfBirth; @Column(nullable=false,length=80) private String country; @Column(nullable=false) private boolean guardianConsent; public Long getId(){return id;} public void setTeam(Team v){team=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getCountry(){return country;} public void setCountry(String v){country=v;} public boolean isGuardianConsent(){return guardianConsent;} public void setGuardianConsent(boolean v){guardianConsent=v;} }
